import { Component, EventEmitter, Input } from '@angular/core';
import { ProductoCarrito } from 'src/app/models/carrito';

@Component({
  selector: 'app-latder',
  templateUrl: './latder.component.html',
  styleUrls: ['./latder.component.css']
})
export class LatderComponent {
  @Input() productoAgregado = new EventEmitter<ProductoCarrito>();

  constructor(private carritoComponent: CarritoComponent) {}

  onProductoAgregado(producto: ProductoCarrito) {
  this.carritoComponent.onProductoAgregado(producto);
  }
}
